"use strict";(self.webpackChunk_positive_intentions_dim=self.webpackChunk_positive_intentions_dim||[]).push([[395],{"./src/stories/08-Tutorial-0-Overview.stories.js":(__unused_webpack_module,__webpack_exports__,__webpack_require__)=>{__webpack_require__.r(__webpack_exports__),__webpack_require__.d(__webpack_exports__,{StartHere:()=>StartHere,__namedExportsOrder:()=>__namedExportsOrder,default:()=>__WEBPACK_DEFAULT_EXPORT__});var react__WEBPACK_IMPORTED_MODULE_0__=__webpack_require__("./node_modules/react/index.js");const __WEBPACK_DEFAULT_EXPORT__={title:"Tutorial/Overview",parameters:{layout:"fullscreen",docs:{description:{component:'\n# Dim Tutorial\n\nDim is a **functional web-components** framework: React-like hooks, an owned\ntemplate renderer (`html` / `css`), Shadow DOM, and **no virtual DOM**.\n\nYou do **not** need React to follow this tutorial. Basic HTML and JavaScript\nare enough.\n\n## What you will build\n\n**Dim Notes** — a small notes app that grows lesson by lesson:\n\n- Cards, lists, and an editor\n- Search, theme, and persisted notes\n- Optional encryption\n- List ↔ detail motion\n- Export / import as files\n\n## Three tracks\n\n1. **Basics** — what a web component is, then Dim’s `define`, templates, state, props, and Shadow DOM styling\n2. **Building an app** — effects, refs, persistence, motion, files, and the full Dim Notes app\n3. **Advanced** — React interop, how Dim works inside, and the rules of hooks\n\n## How to read each lesson\n\n1. **Goal** — what this step teaches\n2. **New words** — terms you will see in the live example\n3. **Why it matters** — how it shows up in Dim Notes\n4. **Try this** — numbered clicks and what you should see\n5. **Snippet** — the smallest working code\n6. **Common mistake** — one pitfall and the fix\n7. **Next** — the following lesson\n\nImport from the public API:\n\n```javascript\nimport { define, html, css, useState } from "../core/index.ts";\n// src/core/dim.ts re-exports the same surface.\n```\n\n## Glossary\n\n| Term | Meaning |\n| --- | --- |\n| **Custom element** | A tag you register with the browser (`tut-note-card`). Tag names must contain a hyphen. |\n| **Tag name** | The string in HTML, e.g. `<tut-note-card>`. |\n| **Host** | The custom-element instance itself (the outer node). |\n| **Shadow DOM** | A private DOM tree attached to the host. Page CSS does not leak in. |\n| **Shadow root** | The root of that private tree (`element.shadowRoot`). |\n| **Attribute** | A string on the HTML tag: `title="Hello"`. Always text. |\n| **Property** | A JavaScript value on the element: objects, functions, booleans. Use `.props` or `.value=`. |\n| **Event** | Something the user (or browser) did, e.g. a click. Bind with `@click=`. |\n| **Template** | The `html` tagged template that describes the shadow tree. |\n| **Hook** | A function like `useState` that Dim calls in the same order every render. |\n| **Re-render** | Dim runs your component function again and updates only what changed. |\n| **Persistence** | Saving state so it survives a refresh (IndexedDB via `useStore`). |\n        '}}},tags:["autodocs"]},StartHere={render:()=>react__WEBPACK_IMPORTED_MODULE_0__.createElement("div",{style:{fontFamily:"system-ui, sans-serif",maxWidth:720,margin:"2rem auto",padding:"1.5rem",lineHeight:1.5}},react__WEBPACK_IMPORTED_MODULE_0__.createElement("p",{style:{color:"#029cfd",fontWeight:700,letterSpacing:"0.08em",fontSize:12}},"TUTORIAL"),react__WEBPACK_IMPORTED_MODULE_0__.createElement("h1",{style:{marginTop:4}},"Start here"),react__WEBPACK_IMPORTED_MODULE_0__.createElement("p",null,"Open Tutorial / 1. Basics / 1. What is a web component? when you are ready. Use the Docs tab on each lesson for Goal, New words, Try this, and the snippet."),react__WEBPACK_IMPORTED_MODULE_0__.createElement("ol",null,react__WEBPACK_IMPORTED_MODULE_0__.createElement("li",null,"Basics — web components, define, templates, state, props, styling"),react__WEBPACK_IMPORTED_MODULE_0__.createElement("li",null,"Building an app — effects, refs, store, motion, files, Dim Notes"),react__WEBPACK_IMPORTED_MODULE_0__.createElement("li",null,"Advanced — React, internals, pitfalls"))),name:"Start here"},__namedExportsOrder=["StartHere"];StartHere.parameters={...StartHere.parameters,docs:{...StartHere.parameters?.docs,source:{originalSource:'{\n  render: () => React.createElement("div", {\n    style: {\n      fontFamily: "system-ui, sans-serif",\n      maxWidth: 720,\n      margin: "2rem auto",\n      padding: "1.5rem",\n      lineHeight: 1.5\n    }\n  }, React.createElement("p", {\n    style: {\n      color: "#029cfd",\n      fontWeight: 700,\n      letterSpacing: "0.08em",\n      fontSize: 12\n    }\n  }, "TUTORIAL"), React.createElement("h1", {\n    style: {\n      marginTop: 4\n    }\n  }, "Start here"), React.createElement("p", null, "Open Tutorial / 1. Basics / 1. What is a web component? when you are ready. Use the Docs tab on each lesson for Goal, New words, Try this, and the snippet."), React.createElement("ol", null, React.createElement("li", null, "Basics — web components, define, templates, state, props, styling"), React.createElement("li", null, "Building an app — effects, refs, store, motion, files, Dim Notes"), React.createElement("li", null, "Advanced — React, internals, pitfalls"))),\n  name: "Start here"\n}',...StartHere.parameters?.docs?.source}}}}}]);